141	async function handleUserMessage(
142	  ws: WebSocket,
143	  session: ChatSession,
144	  orchestrator: ChatOrchestrator,
145	  content: string,
146	  signal: AbortSignal | undefined
147	): Promise<void> {
148	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
149	
150	  const userEntry = createUserEntry(content);
151	  const userIndex = appendEntry(session, userEntry);
152	  sendUpsert(ws, userIndex, userEntry);
153	
154	  const parser = new ThinkingTagParser();
155	  const state: StreamState = {
156	    thinkingIndex: null,
157	    assistantIndex: null,
158	    suppressOutput: false,
159	    sentAssistantIndices: [],
160	  };
161	
162	  let textChunkCount = 0;
163	
164	  try {
165	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
166	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
167	      if (signal?.aborted) break;
168	      textChunkCount = logChunk(chunk, textChunkCount);
169	      processChunk(ws, session, state, parser, chunk);
170	    }
171	  } finally {
172	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
173	    flushHeldText(ws, session, state, parser);
174	    closeCutOff(ws, session, state, 'thinkingIndex');
175	    closeCutOff(ws, session, state, 'assistantIndex');
176	  }
177	
178	  if (textChunkCount > 0) {
179	    log.debug('stream', `received ${textChunkCount} text chunks`);
180	  }
181	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
182	}
