184	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
185	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
186	  if (chunk.type === 'text') return textChunkCount + 1;
187	
188	  if (textChunkCount > 0) {
189	    log.debug('stream', `received ${textChunkCount} text chunks`);
190	  }
191	
192	  if (chunk.type === 'tool_result') {
193	    log.debug('stream', 'tool_result chunk', {
194	      messageCount: chunk.clientMessages.length,
195	      types: chunk.clientMessages.map(m => m.type),
196	    });
197	    return 0;
198	  }
199	
200	  log.debug('stream', 'chunk', {type: chunk.type});
201	  return 0;
202	}
