204	function processChunk(
205	  ws: WebSocket,
206	  session: ChatSession,
207	  state: StreamState,
208	  parser: ThinkingTagParser,
209	  chunk: MessageChunk
210	): void {
211	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
212	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
213	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
214	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
215	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
216	}
