218	function processTextChunk(
219	  ws: WebSocket,
220	  session: ChatSession,
221	  state: StreamState,
222	  parser: ThinkingTagParser,
223	  text: string
224	): void {
225	  const segments = parser.push(text);
226	  for (const segment of segments) {
227	    handleTextSegment(ws, session, state, segment);
228	  }
229	}
