231	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
232	  if (segment.type === 'thinking') {
233	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
234	    return;
235	  }
236	  commitAndClear(ws, session, state, 'thinkingIndex');
237	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
238	}
