240	function streamSegment(
241	  ws: WebSocket,
242	  session: ChatSession,
243	  state: StreamState,
244	  key: StateIndexKey,
245	  createEntry: EntryFactory,
246	  content: string
247	): void {
248	  const isNew = initSegment(session, state, key, createEntry);
249	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
250	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
251	  appendDelta(session, state[key]!, content);
252	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
253	}
254	
255	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
256	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
257	  markSuppressed(session, index);
258	  sendSkip(ws, index);
259	}
260	
261	function markSuppressed(session: ChatSession, index: number): void {
262	  const entry = session.entries[index];
263	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
264	}
265	
266	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
267	  if (state[key] !== null) return false;
268	  state[key] = appendEntry(session, createEntry());
269	  return true;
270	}
271	
272	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
273	  const index = state[key];
274	  if (index === null) return;
275	
276	  commitEntry(session, index);
277	  state[key] = null;
278	
279	  // Only what the client received can be retracted, and only assistant entries.
280	  if (state.suppressOutput) return;
281	
282	  sendCommit(ws, index);
283	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
284	}
285	
286	function processToolUseChunk(
287	  ws: WebSocket,
288	  session: ChatSession,
289	  toolCall: {name: string; input: Record<string, unknown>}
290	): void {
291	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
292	  const toolIndex = appendEntry(session, toolEntry);
293	  sendUpsert(ws, toolIndex, toolEntry);
294	}
295	
296	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
297	  for (const msg of clientMessages) {
298	    log.debug('stream', 'forwarding client message to frontend', {
299	      type: msg.type,
300	      index: 'index' in msg ? msg.index : undefined,
301	    });
302	    sendJson(ws, msg);
303	  }
304	}
305	
306	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
307	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
308	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
309	  commitOpenEntries(ws, session, state);
310	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
311	
312	  for (const idx of state.sentAssistantIndices) {
313	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
314	    markSuppressed(session, idx);
315	  }
316	
317	  state.sentAssistantIndices = [];
318	  state.suppressOutput = true;
319	}
320	
321	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
322	  flushHeldText(ws, session, state, parser);
323	  commitOpenEntries(ws, session, state);
324	}
325	
326	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
327	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
328	  for (const segment of parser.flush()) {
329	    handleTextSegment(ws, session, state, segment);
330	  }
331	}
332	
333	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
334	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
335	  const index = state[key];
336	  if (index === null) return;
337	  markTruncated(session, index);
338	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
339	  commitAndClear(ws, session, state, key);
340	}
341	
342	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
343	  commitAndClear(ws, session, state, 'thinkingIndex');
344	  commitAndClear(ws, session, state, 'assistantIndex');
345	}
346	
347	async function handleListSessions(
348	  ws: WebSocket,
349	  session: ChatSession,
350	  sessionStore: SessionStore | undefined,
351	  message: ListSessionsMessage
352	): Promise<void> {
353	  if (!sessionStore?.listFor) {
354	    sendJson(ws, {type: 'session_list', sessions: []});
355	    return;
356	  }
357	
358	  try {
359	    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
360	    const sessions = summaries.map(s => ({
361	      sessionId: s.sessionId,
362	      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : s.createdAt,
363	      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : s.updatedAt,
364	      entryCount: s.entryCount,
365	    }));
366	    sendJson(ws, {type: 'session_list', sessions});
367	  } catch (error) {
368	    const message = error instanceof Error ? error.message : 'Unknown error';
369	    log.error('ws', 'list_sessions failed', {userId: session.userId, error: message});
370	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to retrieve conversation list');
371	  }
372	}
373	
374	function handlePing(ws: WebSocket, timestamp: number): void {
375	  ws.send(JSON.stringify({type: 'pong', timestamp}));
376	}
